    AUDIT_EVIDENCE_CHARS = 9000
    SEARCH_TIMEOUT_S = 18.0
    TURN_TIMEOUT_S = 75.0
    BRIEF_TIMEOUT_S = 50.0
    TASK_TOTAL_BUDGET_SECONDS = 235.0

